package activerecord

// Структура используемая для сбора статистики по запросам
type MockerLogger struct {
	// Название моккера
	MockerName string

	// Вызовы моккера для создания списка моков
	Mockers string

	// Получение списка фикстур для моков
	FixturesSelector string

	// Название пакета для которого необходимо добавить моки
	ResultName string

	// Результат возвращаемый селектором
	Results any
}

package serializer

import (
	"errors"
	"reflect"
	"testing"

	"github.com/mailru/activerecord/pkg/serializer/errs"
)

type Services struct {
	Quota uint64
	Flags map[string]bool
	Gift  *Gift
	Other map[string]interface{} `mapstructure:",remain"`
}

type Gift struct {
	GiftInterval string `mapstructure:"gift_interval" json:"gift_interval"`
	GiftQuota    uint64 `mapstructure:"gift_quota" json:"gift_quota"`
	GiftibleID   string `mapstructure:"giftible_id" json:"giftible_id"`
}

func TestMapstructureUnmarshal(t *testing.T) {
	type args struct {
		val string
	}
	tests := []struct {
		name    string
		args    args
		exec    func(string) (any, error)
		want    any
		wantErr error
	}{
		{
			name: "simple",
			args: args{val: `{"quota": 2373874}`},
			exec: func(val string) (any, error) {
				var got Services
				err := MapstructureUnmarshal(val, &got)
				return got, err
			},
			want:    Services{Quota: 2373874},
			wantErr: nil,
		},
		{
			name: "with nested map",
			args: args{val: `{"quota": 234321523, "flags": {"UF": true, "OS": true}}`},
			exec: func(val string) (any, error) {
				var got Services
				err := MapstructureUnmarshal(val, &got)
				return got, err
			},
			want:    Services{Quota: 234321523, Flags: map[string]bool{"UF": true, "OS": true}},
			wantErr: nil,
		},
		{
			name: "with nested struct",
			args: args{val: `{"quota": 234321523, "gift": {"giftible_id": "year2020_333_1", "gift_quota": 2343432784}}`},
			exec: func(val string) (any, error) {
				var got Services
				err := MapstructureUnmarshal(val, &got)
				return got, err
			},
			want:    Services{Quota: 234321523, Gift: &Gift{GiftibleID: "year2020_333_1", GiftQuota: 2343432784}},
			wantErr: nil,
		},
		{
			name: "bad input",
			args: args{val: `{"quota": 234321523, "gift": }}}}}}}}}}`},
			exec: func(val string) (any, error) {
				var got Services
				err := MapstructureUnmarshal(val, &got)
				return got, err
			},
			want:    nil,
			wantErr: errs.ErrUnmarshalJSON,
		},
		{
			name: "mapstructure remain",
			args: args{val: `{"quota": 234321523, "unknown_field": "unknown"}`},
			exec: func(val string) (any, error) {
				var got Services
				err := MapstructureUnmarshal(val, &got)
				return got, err
			},
			want:    Services{Quota: 234321523, Other: map[string]interface{}{"unknown_field": "unknown"}},
			wantErr: nil,
		},
		{
			name: "mapstructure err unused",
			args: args{val: `{"quota": 234321523, "unused_field": "unused"}`},
			exec: func(val string) (any, error) {
				// Декодируем в структуру без поля c тегом `mapstructure:",remain"`
				var got struct {
					Quota uint64
				}
				err := MapstructureUnmarshal(val, &got)
				return got, err
			},
			want:    nil,
			wantErr: errs.ErrMapstructureDecode,
		},
		{
			name: "mapstructure err create decoder",
			args: args{val: `{"quota": 2373874}`},
			exec: func(val string) (any, error) {
				var got Services
				// В mapstructurе вторым параметром надо отдавать pointer
				err := MapstructureUnmarshal(val, got)
				return got, err
			},
			want:    nil,
			wantErr: errs.ErrMapstructureNewDecoder,
		},
	}

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := tt.exec(tt.args.val)
			if tt.wantErr != err && !errors.Is(err, tt.wantErr) {
				t.Errorf("MapstructureUnmarshal() error = %v, wantErr %v", err, tt.wantErr)
			}
			if tt.wantErr == nil && !reflect.DeepEqual(got, tt.want) {
				t.Errorf("MapstructureUnmarshal() = %v, want %v", got, tt.want)
			}
		})
	}
}

package octopus

import (
	"log"
	"reflect"
	"testing"

	"github.com/mailru/activerecord/pkg/iproto/iproto"
)

func TestMockServer_ProcessRequest(t *testing.T) {
	logger := NewMockMockServerLogger(t)

	pk := append([][]byte{}, PackString([]byte{}, "pk", iproto.ModeDefault))

	var keysPacked [][][]byte

	for _, key := range []string{"key1"} {
		var keysField [][]byte
		keysField = append(keysField, PackString([]byte{}, key, iproto.ModeDefault))
		keysPacked = append(keysPacked, keysField)
	}

	type fields struct {
		oft []FixtureType
	}
	type args struct {
		msg uint8
		req []byte
	}
	tests := []struct {
		name   string
		fields fields
		args   args
		want   []byte
		wantEx bool
		mocks  func(t *testing.T)
	}{
		{
			name: "simple check ProcessRequest",
			fields: fields{
				oft: []FixtureType{
					{
						ID:       1,
						Msg:      RequestTypeSelect,
						Request:  []byte("aassdd"),
						Response: []byte("zzxxcc"),
					},
				},
			},
			args: args{
				msg: uint8(RequestTypeSelect),
				req: []byte("aassdd"),
			},
			want:   []byte("zzxxcc"),
			wantEx: true,
		},
		{
			name: "Select message type",
			fields: fields{
				oft: []FixtureType{
					{
						ID:       1,
						Msg:      RequestTypeSelect,
						Request:  PackSelect(1, 0, 0, 10, keysPacked),
						Response: []byte("select ok"),
					},
				},
			},
			args: args{
				msg: uint8(RequestTypeSelect),
				req: PackSelect(1, 0, 0, 10, keysPacked),
			},
			want:   []byte("select ok"),
			wantEx: true,
		},
		{
			name: "Select message type (not found)",
			fields: fields{
				oft: []FixtureType{
					{
						ID:      1,
						Msg:     RequestTypeSelect,
						Request: PackSelect(1, 0, 0, 10, keysPacked),
						Response: PackResponse([][]byte{
							[]byte("f1"),
							[]byte("f2")},
						),
					},
				},
			},
			args: args{
				msg: uint8(RequestTypeSelect),
				req: PackSelect(1, 0, 0, 1, keysPacked),
			},
			want:   nil,
			wantEx: false,
			mocks: func(t *testing.T) {
				logger.EXPECT().DebugSelectRequest(uint32(1), uint32(0), uint32(0), uint32(1), keysPacked, SelectMockFixture{
					Indexnum:   0,
					Offset:     0,
					Limit:      10,
					Keys:       keysPacked,
					RespTuples: []TupleData{{Cnt: uint32(2), Data: [][]byte{[]byte("f1"), []byte("f2")}}},
				})
			},
		},
		{
			name: "Call procedure message type (not found)",
			fields: fields{
				oft: []FixtureType{
					{
						ID:      1,
						Msg:     RequestTypeCall,
						Request: PackLua("foo", "a1", "a2"),
						Response: PackResponse([][]byte{
							[]byte("status"),
							[]byte("data")},
						),
					},
				},
			},
			args: args{
				msg: uint8(RequestTypeCall),
				req: PackLua("foo"),
			},
			want:   nil,
			wantEx: false,
			mocks: func(t *testing.T) {
				logger.EXPECT().DebugCallRequest(
					"foo",
					[][]byte{},
					CallMockFixture{
						ProcName:   "foo",
						Args:       [][]byte{[]byte("a1"), []byte("a2")},
						RespTuples: []TupleData{{Cnt: uint32(2), Data: [][]byte{[]byte("status"), []byte("data")}}},
					},
				)
			},
		},
		{
			name: "Insert message type (not found)",
			fields: fields{
				oft: []FixtureType{
					{
						ID:       2,
						Msg:      RequestTypeInsert,
						Request:  PackInsertReplace(2, InsertModeInserOrReplace, [][]byte{[]byte("i1")}),
						Response: nil,
					},
				},
			},
			args: args{
				msg: uint8(RequestTypeInsert),
				req: PackInsertReplace(2, InsertModeInserOrReplace, [][]byte{[]byte("i2")}),
			},
			wantEx: false,
			mocks: func(t *testing.T) {
				logger.EXPECT().DebugInsertRequest(uint32(2), true, InsertModeInserOrReplace, TupleData{Cnt: uint32(1), Data: [][]byte{[]byte("i2")}}, InsertMockFixture{
					NeedRetVal: true,
					InsertMode: InsertModeInserOrReplace,
					Tuple:      TupleData{Cnt: uint32(1), Data: [][]byte{[]byte("i1")}},
				})
			},
		},
		{
			name: "Update message type (not found)",
			fields: fields{
				oft: []FixtureType{
					{
						ID:  1,
						Msg: RequestTypeUpdate,
						Request: PackUpdate(42, pk, []Ops{
							{
								Field: 1,
								Op:    OpSet,
								Value: []byte("u1"),
							},
							{
								Field: 2,
								Op:    OpSet,
								Value: []byte("u2"),
							},
						}),
						Response: PackResponse([][]byte{}),
					},
				},
			},
			args: args{
				msg: uint8(RequestTypeUpdate),
				req: PackUpdate(42, pk, []Ops{
					{
						Field: 1,
						Op:    OpSet,
						Value: []byte("u1"),
					},
				}),
			},
			wantEx: false,
			mocks: func(t *testing.T) {
				logger.EXPECT().DebugUpdateRequest(
					uint32(42),
					pk,
					[]Ops{
						{
							Field: 1,
							Op:    OpSet,
							Value: []byte("u1"),
						},
					},
					UpdateMockFixture{
						PrimaryKey: pk,
						UpdateOps: []Ops{
							{
								Field: 1,
								Op:    OpSet,
								Value: []byte("u1"),
							},
							{
								Field: 2,
								Op:    OpSet,
								Value: []byte("u2"),
							},
						},
					})
			},
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			if tt.mocks != nil {
				tt.mocks(t)
			}

			oms := &MockServer{
				oft:    tt.fields.oft,
				logger: logger,
			}

			got, ex := oms.ProcessRequest(tt.args.msg, tt.args.req)
			if !reflect.DeepEqual(got, tt.want) {
				t.Errorf("MockServer.ProcessRequest() got = %v, want %v", got, tt.want)
			}

			if ex != tt.wantEx {
				t.Errorf("MockServer.ProcessRequest() exist = %v, want %v", ex, tt.wantEx)
			}
		})
	}
}

func PackResponse(data [][]byte) []byte {
	var tuples [][][]byte

	tuples = append(tuples, data)

	resp, err := PackResopnseStatus(RcOK, tuples)
	if err != nil {
		log.Fatal(err)
	}

	return resp
}

package activerecord

import (
	"reflect"
	"sync"
	"testing"
)

type TestOptions struct {
	hash string
	mode ServerModeType
}

func (to *TestOptions) InstanceMode() ServerModeType {
	return to.mode
}

func (to *TestOptions) GetConnectionID() string {
	return to.hash
}

type TestConnection struct {
	ch chan struct{}
	id string
}

func (tc *TestConnection) Close() {
	tc.ch <- struct{}{}
}

func (tc *TestConnection) Done() <-chan struct{} {
	return tc.ch
}

var connectionCall = 0

func connectorFunc(options interface{}) (ConnectionInterface, error) {
	connectionCall++
	to, _ := options.(*TestOptions)
	return &TestConnection{id: to.hash}, nil
}

func Test_connectionPool_Add(t *testing.T) {
	to1 := &TestOptions{hash: "testopt1"}

	var clusterInfo = NewClusterInfo(
		WithShard([]OptionInterface{to1}, []OptionInterface{}),
	)

	type args struct {
		shard     ShardInstance
		connector func(interface{}) (ConnectionInterface, error)
	}

	tests := []struct {
		name    string
		args    args
		want    ConnectionInterface
		wantErr bool
		wantCnt int
	}{
		{
			name: "first connection",
			args: args{
				shard:     clusterInfo.NextMaster(0),
				connector: connectorFunc,
			},
			wantErr: false,
			want:    &TestConnection{id: "testopt1"},
			wantCnt: 1,
		},
		{
			name: "again first connection",
			args: args{
				shard:     clusterInfo.NextMaster(0),
				connector: connectorFunc,
			},
			wantErr: true,
			wantCnt: 1,
		},
	}

	cp := connectionPool{
		lock:      sync.Mutex{},
		container: map[string]ConnectionInterface{},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := cp.Add(tt.args.shard, tt.args.connector)
			if (err != nil) != tt.wantErr {
				t.Errorf("connectionPool.Add() error = %v, wantErr %v", err, tt.wantErr)
				return
			}
			if !reflect.DeepEqual(got, tt.want) {
				t.Errorf("connectionPool.Add() = %+v, want %+v", got, tt.want)
			}
			if connectionCall != tt.wantCnt {
				t.Errorf("connectionPool.Add() connectionCnt = %v, want %v", connectionCall, tt.wantCnt)
			}
		})
	}
}

