package serializer

import (
	"errors"
	"reflect"
	"testing"

	"github.com/mailru/activerecord/pkg/serializer/errs"
)

func TestPrintfUnmarshal(t *testing.T) {
	type args struct {
		val string
	}
	tests := []struct {
		name    string
		args    args
		want    float64
		wantErr error
	}{
		{
			name:    "simple",
			args:    args{val: `1.223`},
			want:    1.223,
			wantErr: nil,
		},
		{
			name:    "err",
			args:    args{val: `{"key": {"nestedkey": "value}}`},
			want:    0,
			wantErr: errs.ErrPrintfParse,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			var got float64
			err := PrintfUnmarshal("", tt.args.val, &got)
			if tt.wantErr != err && !errors.Is(err, tt.wantErr) {
				t.Errorf("PrintfUnmarshal() error = %v, wantErr %v", err, tt.wantErr)
			}
			if tt.wantErr == nil && !reflect.DeepEqual(got, tt.want) {
				t.Errorf("PrintfUnmarshal() = %v, want %v", got, tt.want)
			}
		})
	}
}

package octopus

import (
	"context"
	"testing"
	"time"
)

func Test_prepareConnection(t *testing.T) {
	type args struct {
		server string
		opts   []ConnectionOption
	}
	tests := []struct {
		name    string
		args    args
		want    string
		wantErr bool
	}{
		{
			name: "connectionHash",
			args: args{
				server: "127.0.0.1",
				opts:   []ConnectionOption{},
			},
			want:    "ff9ed3cc",
			wantErr: false,
		},
		{
			name: "same connectionHash",
			args: args{
				server: "127.0.0.1",
				opts:   []ConnectionOption{},
			},
			want:    "ff9ed3cc",
			wantErr: false,
		},
		{
			name: "connectionHash with options",
			args: args{
				server: "127.0.0.1",
				opts: []ConnectionOption{
					WithTimeout(time.Millisecond*50, time.Millisecond*100),
				},
			},
			want:    "f855b29a",
			wantErr: false,
		},
		{
			name: "yes another connectionHash with options",
			args: args{
				server: "127.0.0.1",
				opts: []ConnectionOption{
					WithTimeout(time.Millisecond*50, time.Millisecond*100),
					WithIntervals(time.Second*50, time.Second*50, time.Second*50),
				},
			},
			want:    "fdef5d9b",
			wantErr: false,
		},
		{
			name: "yes another connectionHash with options",
			args: args{
				server: "",
				opts: []ConnectionOption{
					WithTimeout(time.Millisecond*50, time.Millisecond*100),
					WithIntervals(time.Second*50, time.Second*50, time.Second*50),
				},
			},
			want:    "",
			wantErr: true,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := NewOptions(tt.args.server, ModeMaster, tt.args.opts...)
			if (err != nil) != tt.wantErr {
				t.Errorf("prepareConnection() error = %v, wantErr %v", err, tt.wantErr)
				return
			}
			if !tt.wantErr && got.GetConnectionID() != tt.want {
				t.Errorf("prepareConnection() Hex = %v, want %v", got.GetConnectionID(), tt.want)
			}
		})
	}
}

func TestGetConnection(t *testing.T) {
	type args struct {
		ctx    context.Context
		server string
		opts   []ConnectionOption
	}
	tests := []struct {
		name    string
		args    args
		want    []string
		wantErr bool
	}{
		{
			name: "first connection",
			args: args{
				ctx:    context.Background(),
				server: "127.0.0.1:11211",
				opts:   []ConnectionOption{},
			},
			wantErr: false,
			want:    []string{""},
		},
	}

	oms, err := InitMockServer(WithHost("127.0.0.1", "11211"))
	if err != nil {
		t.Fatalf("error init octopusMock %s", err)
		return
	}

	err = oms.Start()
	if err != nil {
		t.Fatalf("error start octopusMock %s", err)
		return
	}

	defer func() {
		err := oms.Stop()
		if err != nil {
			t.Fatalf("error stop octopusMock %s", err)
		}
	}()

	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			octopusOpts, err := NewOptions(tt.args.server, ModeMaster, tt.args.opts...)
			if err != nil {
				t.Errorf("can't initialize options: %s", err)
			}
			_, err = GetConnection(tt.args.ctx, octopusOpts)
			if (err != nil) != tt.wantErr {
				t.Errorf("GetConnection() error = %v, wantErr %v", err, tt.wantErr)
				return
			}
		})
	}
}

package serializer

import (
	"errors"
	"reflect"
	"testing"

	"github.com/mailru/activerecord/pkg/serializer/errs"
)

func TestJSONUnmarshal(t *testing.T) {
	type args struct {
		val string
	}
	tests := []struct {
		name    string
		args    args
		exec    func(string) (any, error)
		want    any
		wantErr error
	}{
		{
			name: "simple map",
			args: args{val: `{"key": "value"}`},
			exec: func(val string) (any, error) {
				var got map[string]interface{}
				err := JSONUnmarshal(val, &got)
				return got, err
			},
			want:    map[string]interface{}{"key": "value"},
			wantErr: nil,
		},
		{
			name: "nested map",
			args: args{val: `{"key": {"nestedkey": "value"}}`},
			exec: func(val string) (any, error) {
				var got map[string]interface{}
				err := JSONUnmarshal(val, &got)
				return got, err
			},
			want:    map[string]interface{}{"key": map[string]interface{}{"nestedkey": "value"}},
			wantErr: nil,
		},
		{
			name: "err map unmarshal",
			args: args{val: `{"key": {"nestedkey": "value}}`},
			exec: func(val string) (any, error) {
				var got map[string]interface{}
				err := JSONUnmarshal(val, &got)
				return got, err
			},
			want:    nil,
			wantErr: errs.ErrUnmarshalJSON,
		},
		{
			name: "simple custom type ",
			args: args{val: `{"quota": 2373874}`},
			exec: func(val string) (any, error) {
				var got Services
				err := JSONUnmarshal(val, &got)
				return got, err
			},
			want:    Services{Quota: 2373874},
			wantErr: nil,
		},
		{
			name: "nested custom type",
			args: args{val: `{"quota": 234321523, "gift": {"giftible_id": "year2020_333_1", "gift_quota": 2343432784}}`},
			exec: func(val string) (any, error) {
				var got Services
				err := JSONUnmarshal(val, &got)
				return got, err
			},
			want:    Services{Quota: 234321523, Gift: &Gift{GiftibleID: "year2020_333_1", GiftQuota: 2343432784}},
			wantErr: nil,
		},
		{
			name: "err custom type",
			args: args{val: `{"quota": 234321523, "gift": }}}}}}}}}}`},
			exec: func(val string) (any, error) {
				var got Services
				err := JSONUnmarshal(val, &got)
				return got, err
			},
			want:    nil,
			wantErr: errs.ErrUnmarshalJSON,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := tt.exec(tt.args.val)
			if tt.wantErr != err && !errors.Is(err, tt.wantErr) {
				t.Errorf("JSONUnmarshal() error = %v, wantErr %v", err, tt.wantErr)
			}
			if tt.wantErr == nil && !reflect.DeepEqual(got, tt.want) {
