			}
		})
	}
}

package syncutil

import (
	"runtime"
	"sync"
	"sync/atomic"
	"testing"
	"time"
)

func TestThrottleDo(t *testing.T) {
	t.Skip("Fails on centos")
	th := NewThrottle(time.Millisecond * 50)

	var (
		wg sync.WaitGroup
		n  int32
	)
	for i := 0; i < runtime.NumCPU(); i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			tick := time.Tick(time.Millisecond * 5)
			for j := 0; j < 100; j++ {
				<-tick
				if th.Next() {
					atomic.AddInt32(&n, 1)
				}
			}
		}()
	}
	wg.Wait()

	if act, exp := int(atomic.LoadInt32(&n)), 10; act != exp {
		t.Errorf("got %d truly Next(); want %d", act, exp)
	}
}

func BenchmarkThrottleDo(b *testing.B) {
	th := NewThrottle(time.Millisecond * 10)
	b.RunParallel(func(pb *testing.PB) {
		for pb.Next() {
			th.Next()
		}
	})
}

package ds

import (
	"testing"
)

func Test_getImportName(t *testing.T) {
	type args struct {
		path string
	}
	tests := []struct {
		name    string
		args    args
		want    string
		wantErr bool
	}{
		{
			name:    "simple getImportName",
			args:    args{path: "go/ast"},
			want:    "ast",
			wantErr: false,
		},
		{
			name:    "small package path",
			args:    args{path: "ast"},
			want:    "ast",
			wantErr: false,
		},
		{
			name:    "gitlab package",
			args:    args{path: "github.com/mailru/activerecord/internal/pkg/arerror"},
			want:    "arerror",
			wantErr: false,
		},
		{
			name:    "import with quote",
			args:    args{path: `error "github.com/mailru/activerecord/internal/pkg/arerror"`},
			want:    "arerror",
			wantErr: false,
		},
		{
			name:    "empty import",
			args:    args{path: ""},
			want:    "",
			wantErr: true,
		},
	}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			got, err := getImportName(tt.args.path)
			if (err != nil) != tt.wantErr {
				t.Errorf("getImportName() error = %v, wantErr %v", err, tt.wantErr)
				return
			}
			if got != tt.want {
				t.Errorf("getImportName() = %v, want %v", got, tt.want)
			}
		})
	}
}

package iproto_test

import (
	"testing"
	"time"

	"github.com/mailru/activerecord/pkg/iproto/iproto"
	"github.com/mailru/activerecord/pkg/iproto/iproto/internal/testutil"
	"github.com/mailru/activerecord/pkg/iproto/util/pool"
	"golang.org/x/net/context"
)

func handler(ctx context.Context, rw iproto.Conn, pkt iproto.Packet) {
	_ = rw.Send(ctx, iproto.ResponseTo(pkt, nil))
}

func benchmarkHandler(b *testing.B, h iproto.Handler) {
	var p iproto.Packet
	rw := testutil.NewFakeResponseWriter()
	rw.DoSend = func(context.Context, iproto.Packet) error {
		// emulate some work
		time.Sleep(time.Microsecond)
		return nil
	}
	ctx := context.Background()

	for i := 0; i < b.N; i++ {
		h.ServeIProto(ctx, rw, p)
	}
}

func BenchmarkHandlerPlain(b *testing.B) {
	benchmarkHandler(b, iproto.HandlerFunc(handler))
}

func BenchmarkHandlerParallel(b *testing.B) {
	benchmarkHandler(b, iproto.ParallelHandler(iproto.HandlerFunc(handler), 128))
}

func BenchmarkHandlerPool(b *testing.B) {
	p := pool.Must(pool.New(&pool.Config{
		UnstoppableWorkers: 128,
		MaxWorkers:         128,
		WorkQueueSize:      100,
	}))
	benchmarkHandler(b, iproto.PoolHandler(iproto.HandlerFunc(handler), p))
}
